import {fresh,play,legal,choose,makeAgent} from './engine.js';
const $=id=>document.getElementById(id),worker=new Worker('./worker.js',{type:'module'}),KEY='nested-rl-v1';
let state=fresh(),aMark=1,agents=[makeAgent(),makeAgent()],running=false,mode='watch',tab='watch',count=0,last=null,human=fresh(),humanMark=1,humanTimer=null,history=[],exportPending=false,lastSaved=null,ready=false;
const names=['top left','top middle','top right','middle left','centre','middle right','bottom left','bottom middle','bottom right'];
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),3200);}
function persist(c){lastSaved=c;try{localStorage.setItem(KEY,JSON.stringify(c));$('saveStatus').textContent='✓ Saved on this browser';}catch{$('saveStatus').textContent='Storage unavailable — export to keep progress';}}
let restored=null;try{restored=JSON.parse(localStorage.getItem(KEY)||'null');}catch{}
worker.postMessage({type:'init',data:restored});
worker.onerror=()=>{toast('Training could not start. Reload this page to try again.');$('run').disabled=true;};
worker.onmessage=({data:d})=>{if(d.type==='error'){toast(d.message);if(!ready){ready=true;worker.postMessage({type:'init'});}return;}ready=true;count=d.count;agents=d.agents;running=d.running;mode=d.mode;history=d.history;const n=count||1;$('episodes').textContent=count.toLocaleString();$('winsA').textContent=d.wins[0].toLocaleString();$('winsB').textContent=d.wins[1].toLocaleString();$('aRate').textContent=count?`${Math.round(d.wins[0]/n*100)}% won · ${d.wins[2]} draws`:'Awaiting first game';$('bRate').textContent=count?`${Math.round(d.wins[1]/n*100)}% won · ${d.wins[2]} draws`:'Awaiting first game';$('explore').innerHTML=`${Math.round(d.epsilon*100)}<span>%</span>`;if(d.state){state=d.state;aMark=d.aMark;last=d.last;}if(d.checkpoint){persist(d.checkpoint);if(exportPending){exportPending=false;download(d.checkpoint);}}if(d.type==='benchmark'){const fmt=x=>`${Math.round(x.score*100)}% (${x.wins}W / ${x.draws}D / ${x.losses}L)`;$('benchResult').textContent=`A: ${fmt(d.scores[0])} · B: ${fmt(d.scores[1])} · 80 games each`;$('benchmark').disabled=false;$('benchmark').textContent='Test again ↗';}updateControls();if(tab==='watch')render();renderWeights();if(d.type==='evaluation'||d.type==='saved'||d.type==='frame'&&history.length!==Number($('chart').dataset.points))drawChart();};
function updateControls(){$('run').innerHTML=running?'Ⅱ <span>Pause learning</span>':'▶ <span>Start learning</span>';$('run').disabled=tab==='play';$('step').disabled=running||tab==='play';$('slow').classList.toggle('selected',mode==='watch');$('fast').classList.toggle('selected',mode==='fast');$('speed').disabled=mode==='fast';$('liveBadge').classList.toggle('on',running||tab==='play');$('liveBadge').innerHTML=`<i></i> ${tab==='play'?'CHALLENGE':running?(mode==='fast'?'TRAINING FAST':'LIVE SELF-PLAY'):'PAUSED'}`;$('modeHint').textContent=mode==='fast'?'Train at full speed. Board shows sampled live positions.':'Every move, live. Updates after each game.';}
function render(){const s=tab==='watch'?state:human,am=tab==='watch'?aMark:(Number($('opponent').value)===0?-humanMark:humanMark),moves=legal(s),id=s.turn===am?0:1;const player=s.winner?(s.winner===2?'Draw':tab==='play'?(s.winner===humanMark?'You win!':'Bot wins'):`Agent ${s.winner===am?'A':'B'} wins`):tab==='play'?(s.turn===humanMark?'Your turn':'Bot is thinking…'):`Agent ${id===0?'A':'B'} to move`;$('turnLabel').textContent=player;const mark=document.createElement('span');mark.textContent=s.winner?(s.winner===2?'—':s.winner===1?'×':'○'):s.turn===1?'×':'○';mark.className=(s.winner&&s.winner!==2?s.winner===am:s.turn===am)?'orange':'teal';$('turnLabel').appendChild(mark);$('gameLabel').textContent=tab==='watch'?`SELF-PLAY / GAME ${String(state.winner?count:count+1).padStart(4,'0')}`:`HUMAN VS AGENT ${Number($('opponent').value)===0?'A':'B'} / NO LEARNING`;$('aName').textContent=tab==='play'&&Number($('opponent').value)===1?'You':'A';$('bName').textContent=tab==='play'&&Number($('opponent').value)===0?'You':'B';$('aSymbol').textContent=am===1?'×':'○';$('bSymbol').textContent=am===1?'○':'×';$('moveCount').textContent=`MOVE ${String(s.ply).padStart(2,'0')}`;$('ruleHint').innerHTML='<i class="active-key"></i> '+(s.winner?'Game complete':s.next===-1?'Any open board is available':`Next: ${names[s.next]} board`);const fragment=document.createDocumentFragment();for(let b=0;b<9;b++){const mini=document.createElement('div');mini.className='mini-board'+(moves.some(a=>Math.floor(a/9)===b)?' active':'')+(s.boards[b]?' closed':'')+(s.boards[b]===am?' won-a':s.boards[b]===-am?' won-b':'');mini.setAttribute('aria-label',`${names[b]} board`);for(let c=0;c<9;c++){const a=b*9+c,v=s.cells[a],button=document.createElement('button');button.className='cell'+(v?(v===am?' x':' o'):'')+(a===s.last?' last':'');button.textContent=v===1?'×':v===-1?'○':'';button.setAttribute('aria-label',`${names[b]} board, ${names[c]} cell${v?', '+(v===1?'X':'O'):''}`);button.disabled=!(tab==='play'&&s.turn===humanMark&&moves.includes(a));if(!button.disabled){button.classList.add('legal');button.onclick=()=>humanMove(a);}mini.appendChild(button);}if(s.boards[b]){const owner=document.createElement('div');owner.className='owner '+(s.boards[b]===2?'draw':s.boards[b]===am?'orange':'teal');owner.textContent=s.boards[b]===2?'—':s.boards[b]===1?'×':'○';mini.appendChild(owner);}fragment.appendChild(mini);}$('board').replaceChildren(fragment);if(tab==='watch'){$('moveInfo').textContent=last?`Agent ${last.id===0?'A':'B'} → ${names[Math.floor(last.action/9)]} / ${names[last.action%9]} · ${Math.round(last.prob*100)}% move probability${last.capture?' · Small board claimed':''}${state.winner?' · Both policies updated':''}`:'Press Start learning to watch the first move.';}else $('moveInfo').textContent=s.winner?'Start a new game to try another strategy.':s.turn===humanMark?'You are '+(humanMark===1?'X':'O')+'. Choose an empty cell on a highlighted board.':'The bot is choosing from its current learned policy.';}
function renderWeights(){const indices=[0,1,2,7,8,12,14],labels=['Claim a small board','Block an immediate win','Create a fork','Win the whole game','Block a macro threat','Send to a local threat','Send to macro danger'];$('weights').replaceChildren(...indices.map((j,k)=>{const div=document.createElement('div');div.className='weight-row';div.innerHTML=`<span>${labels[k]}</span><span class="orange">${agents[0].weights[j].toFixed(1)}</span><span class="teal">${agents[1].weights[j].toFixed(1)}</span>`;return div;}));}
function drawChart(){const svg=$('chart'),W=660,H=200,left=34,right=13,top=16,bottom=28,maxX=Math.max(250,history.at(-1)?.episode||0),x=n=>left+n/maxX*(W-left-right),y=n=>top+(1-n)*(H-top-bottom);let content='';for(let n=0;n<=1;n+=.25)content+=`<line x1="${left}" x2="${W-right}" y1="${y(n)}" y2="${y(n)}" stroke="#e6e9de" ${n===.5?'stroke-dasharray="4 4"':''}/><text x="${left-9}" y="${y(n)+3}" text-anchor="end" fill="#929b83" font-size="9">${n*100}%</text>`;for(let k=0;k<=4;k++){const t=Math.round(maxX*k/4);content+=`<text x="${x(t)}" y="${H-8}" text-anchor="middle" fill="#929b83" font-size="9">${t>=1000?(t/1000).toFixed(1)+'k':t}</text>`;}for(const [key,color] of [['a','#d76b3e'],['b','#348679']]){if(history.length)content+=`<polyline points="${history.map(h=>`${x(h.episode)},${y(h[key])}`).join(' ')}" fill="none" stroke="${color}" stroke-width="2.5" stroke-linejoin="round"/>`;for(const h of history)content+=`<circle cx="${x(h.episode)}" cy="${y(h[key])}" r="3" fill="${color}"><title>Game ${h.episode}: ${Math.round(h[key]*100)}%</title></circle>`;}if(history.length<2)content+='<text x="350" y="93" text-anchor="middle" fill="#919b80" font-size="12">A learning curve starts with a first game.</text><text x="350" y="112" text-anchor="middle" fill="#a1a992" font-size="10">Train 250 games to reveal the next checkpoint.</text>';svg.innerHTML=content;svg.dataset.points=history.length;const h=history.at(-1);$('evalSummary').textContent=h?`A ${Math.round(h.a*100)}% · B ${Math.round(h.b*100)}%${h.episode===0?' · untrained':''}`:'Establishing baseline…';}
$('run').onclick=()=>worker.postMessage({type:'run',running:!running});$('step').onclick=()=>worker.postMessage({type:'step'});$('slow').onclick=()=>worker.postMessage({type:'settings',mode:'watch'});$('fast').onclick=()=>worker.postMessage({type:'settings',mode:'fast'});$('speed').oninput=e=>{$('speedLabel').textContent=`${e.target.value} moves / sec`;worker.postMessage({type:'settings',delay:1000/Number(e.target.value)});};$('lr').onchange=e=>worker.postMessage({type:'settings',lr:Number(e.target.value)});$('reset').onclick=()=>{if(confirm('Reset both learned policies and all training history? Export first if you want to keep them.')){worker.postMessage({type:'reset'});$('benchResult').textContent='Try a fixed tactical opponent that wins and blocks.';if(tab==='play')startHuman();}};
function download(c){const u=URL.createObjectURL(new Blob([JSON.stringify(c,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=`nested-checkpoint-${c.count}-games.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),5000);toast('Progress exported');}
$('export').onclick=()=>{exportPending=true;worker.postMessage({type:'save'});};$('import').onclick=()=>$('file').click();$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error('Checkpoint is too large.');const c=JSON.parse(await f.text());worker.postMessage({type:'load',data:c});}catch{toast('Unable to read this checkpoint. Choose a Nested JSON export.');}e.target.value='';};$('benchmark').onclick=()=>{$('benchmark').disabled=true;$('benchmark').textContent='Testing…';worker.postMessage({type:'evaluate'});};
function setTab(t){tab=t;$('watchTab').classList.toggle('selected',t==='watch');$('playTab').classList.toggle('selected',t==='play');$('watchTab').setAttribute('aria-selected',t==='watch');$('playTab').setAttribute('aria-selected',t==='play');$('challengeControls').hidden=t!=='play';clearTimeout(humanTimer);if(t==='play'){worker.postMessage({type:'run',running:false});startHuman();}updateControls();render();}
$('watchTab').onclick=()=>setTab('watch');$('playTab').onclick=()=>setTab('play');function startHuman(){clearTimeout(humanTimer);human=fresh();humanMark=Number($('humanMark').value);render();scheduleBot();}function humanMove(a){if(tab!=='play'||human.turn!==humanMark||!legal(human).includes(a))return;human=play(human,a);render();scheduleBot();}function scheduleBot(){if(tab==='play'&&!human.winner&&human.turn!==humanMark)humanTimer=setTimeout(()=>{const a=choose(human,agents[Number($('opponent').value)].weights).action;human=play(human,a);render();},450);}$('newGame').onclick=startHuman;$('opponent').onchange=startHuman;$('humanMark').onchange=startHuman;
$('aboutBtn').onclick=$('rulesBtn').onclick=()=>$('about').showModal();$('closeAbout').onclick=()=>$('about').close();$('about').onclick=e=>{if(e.target===$('about')){const r=$('about').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('about').close();}};document.addEventListener('visibilitychange',()=>{if(document.hidden)worker.postMessage({type:'save'});});setInterval(()=>{if(running)worker.postMessage({type:'save'});},30000);render();renderWeights();drawChart();
